window.TL = {"duration": 416.89, "scenes": [{"id": "s1", "label": "Opening & Key Takeaway", "start": 0, "end": 39.54}, {"id": "s2", "label": "01. Korean Workbook Market and Competitive Landscape", "start": 39.54, "end": 101.58}, {"id": "s3", "label": "02. JEI's Strengths and Current Limitations", "start": 101.58, "end": 163.2}, {"id": "s4", "label": "03. Parents' Needs and Primary Target Customers", "start": 163.2, "end": 222.01}, {"id": "s5", "label": "04. Core Differentiation: From Assessment to Visible Growth", "start": 222.01, "end": 272.85}, {"id": "s6", "label": "05. Proposed Brand Positioning and Customer Messaging", "start": 272.85, "end": 343.24}, {"id": "s7", "label": "06. Service Development and Operational Directions", "start": 343.24, "end": 392.49}, {"id": "s8", "label": "Closing", "start": 392.49, "end": 416.89}], "cont": ["s1", "s2", "s3", "s4", "s5", "s6", "s7", "s8"], "order": ["l1_1", "l1_2", "l1_3", "l1_4", "l1_5", "l2_1", "l2_2", "l2_3", "l2_4", "l2_5", "l2_6", "l2_7", "l2_8", "l2_9", "l3_1", "l3_2", "l3_3", "l3_4", "l3_5", "l3_6", "l3_7", "l3_8", "l3_9", "l4_1", "l4_2", "l4_3", "l4_4", "l4_5", "l4_6", "l4_7", "l4_8", "l4_9", "l5_1", "l5_2", "l5_3", "l5_4", "l5_5", "l5_6", "l5_7", "l5_8", "l5_9", "l6_1", "l6_2", "l6_3", "l6_4", "l6_5", "l6_6", "l6_7", "l6_8", "l6_9", "l6_10", "l6_11", "l6_12", "l6_13", "l7_1", "l7_2", "l7_3", "l7_4", "l7_5", "l7_6", "l7_7", "l7_8", "l8_1", "l8_2", "l8_3", "l8_4", "l8_5"], "lines": {"l1_1": {"scene": "s1", "text": "Today, I will present JEI's repositioning strategy for the Korean market.", "start": 0.6, "end": 4.95, "words": [["today", 0.57], ["i", 1.13], ["will", 1.19], ["present", 1.35], ["jei's", 1.73], ["repositioning", 2.55], ["strategy", 3.31], ["for", 3.61], ["the", 3.91], ["korean", 4.01], ["market", 4.33]]}, "l1_2": {"scene": "s1", "text": "Our key message to customers is clear.", "start": 5.65, "end": 7.85, "words": [["our", 5.65], ["key", 5.83], ["message", 6.03], ["to", 6.41], ["customers", 6.61], ["is", 7.01], ["clear", 7.23]]}, "l1_3": {"scene": "s1", "text": "JEI can differentiate itself by using precise diagnosis and assessment to design the learning path each child needs, and by helping children develop the ability to grow independently.", "start": 8.55, "end": 19.32, "words": [["jei", 8.55], ["can", 9.37], ["differentiate", 9.61], ["itself", 10.13], ["by", 10.57], ["using", 10.83], ["precise", 11.11], ["diagnosis", 11.61], ["and", 12.13], ["assessment", 12.51], ["to", 12.91], ["design", 13.39], ["the", 13.69], ["learning", 13.89], ["path", 14.13], ["each", 14.49], ["child", 14.79], ["needs", 15.11], ["and", 15.69], ["by", 16.01], ["helping", 16.15], ["children", 16.45], ["develop", 16.81], ["the", 17.19], ["ability", 17.37], ["to", 17.75], ["grow", 17.99], ["independently", 18.29]]}, "l1_4": {"scene": "s1", "text": "To deliver on that promise, we must connect our diagnostic results to each child's actual learning experience and show parents clear evidence of progress.", "start": 20.02, "end": 28.51, "words": [["to", 19.89], ["deliver", 20.17], ["on", 20.45], ["that", 20.67], ["promise", 20.81], ["we", 21.45], ["must", 21.51], ["connect", 21.79], ["our", 22.11], ["diagnostic", 22.31], ["results", 22.79], ["to", 23.27], ["each", 23.49], ["child's", 23.81], ["actual", 24.27], ["learning", 24.67], ["experience", 24.97], ["and", 25.63], ["show", 26.17], ["parents", 26.41], ["clear", 26.79], ["evidence", 27.19], ["of", 27.55], ["progress", 27.75]]}, "l1_5": {"scene": "s1", "text": "I'll begin with the competitive landscape, then discuss JEI's strengths and limitations, what parents need, our proposed brand positioning, and the steps needed to deliver it.", "start": 29.21, "end": 38.99, "words": [["i'll", 29.21], ["begin", 29.39], ["with", 29.63], ["the", 29.79], ["competitive", 29.93], ["landscape", 30.37], ["then", 31.13], ["discuss", 31.39], ["jei's", 31.81], ["strengths", 32.63], ["and", 32.97], ["limitations", 33.17], ["what", 33.97], ["parents", 34.35], ["need", 34.73], ["our", 35.11], ["proposed", 35.31], ["brand", 35.73], ["positioning", 36.03], ["and", 36.83], ["the", 37.25], ["steps", 37.39], ["needed", 37.69], ["to", 38.03], ["deliver", 38.21], ["it", 38.51]]}, "l2_1": {"scene": "s2", "text": "The Korean workbook market has become more competitive, with traditional providers offering increasingly different learning models.", "start": 40.44, "end": 46.78, "words": []}, "l2_2": {"scene": "s2", "text": "Competition now extends beyond workbook providers to local study rooms, private learning centers, and digital learning programs.", "start": 47.48, "end": 54.37, "words": []}, "l2_3": {"scene": "s2", "text": "The four major workbook providers in Korea have different business models and strategies.", "start": 55.07, "end": 59.96, "words": []}, "l2_4": {"scene": "s2", "text": "Daekyo operates learning spaces such as Learning Centers and Hi CAMPUS, and offers learning content through its Summit program.", "start": 60.66, "end": 67.32, "words": []}, "l2_5": {"scene": "s2", "text": "Kumon records students' handwritten work digitally and supports learning between home visits through Daily Care.", "start": 68.02, "end": 73.83, "words": []}, "l2_6": {"scene": "s2", "text": "Woongjin combines learning across all subjects with AI features through its Smart All program.", "start": 74.53, "end": 79.87, "words": []}, "l2_7": {"scene": "s2", "text": "JEI's strengths include paper-based learning, individualized learning paths, precise assessment, and instructor coaching.", "start": 80.57, "end": 87.24, "words": []}, "l2_8": {"scene": "s2", "text": "Among these competitors, Kumon is our most direct competitor because we both focus on paper-based learning and home visits.", "start": 87.94, "end": 94.59, "words": []}, "l2_9": {"scene": "s2", "text": "Therefore, JEI needs to clearly show how we design learning for each child based on assessment results.", "start": 95.29, "end": 101.03, "words": []}, "l3_1": {"scene": "s3", "text": "JEI has five key strengths: precise diagnostic assessment, learning at each child's own pace, step-by-step workbooks, paper-based learning, and instructor coaching.", "start": 102.48, "end": 112.22, "words": []}, "l3_2": {"scene": "s3", "text": "We also have a long history and a strong reputation for quality learning materials.", "start": 112.92, "end": 117.47, "words": []}, "l3_3": {"scene": "s3", "text": "However, parents now have many learning options, including AI and digital programs.", "start": 118.17, "end": 122.96, "words": []}, "l3_4": {"scene": "s3", "text": "So, we need to give parents a clear reason to choose JEI.", "start": 123.66, "end": 127.51, "words": []}, "l3_5": {"scene": "s3", "text": "The problem we want to solve is that assessment results do not always lead to the right learning materials, starting level, or learning pace for each child.", "start": 128.21, "end": 136.0, "words": []}, "l3_6": {"scene": "s3", "text": "Even at JEI Learning Centers, if we assess students only when they first join, or only tell parents how far their child has progressed, parents may still have questions.", "start": 136.7, "end": 145.84, "words": []}, "l3_7": {"scene": "s3", "text": "Assessment results should lead to real changes in each child's learning.", "start": 146.54, "end": 150.45, "words": []}, "l3_8": {"scene": "s3", "text": "We also need to show parents how these changes help their children improve.", "start": 151.15, "end": 155.12, "words": []}, "l3_9": {"scene": "s3", "text": "Simply emphasizing self-learning, personalized learning, or AI is not enough to differentiate JEI from competitors.", "start": 155.82, "end": 162.65, "words": []}, "l4_1": {"scene": "s4", "text": "The first question parents ask is, \"Where is my child having difficulty, and what should my child learn first?\"", "start": 164.1, "end": 169.97, "words": []}, "l4_2": {"scene": "s4", "text": "When sharing assessment results, we should also explain which subject and level their child should start with, as well as the most appropriate learning pace.", "start": 170.67, "end": 178.69, "words": []}, "l4_3": {"scene": "s4", "text": "Parents also want their children to study independently, without constant reminders.", "start": 179.39, "end": 184.05, "words": []}, "l4_4": {"scene": "s4", "text": "Once learning begins, short assignments and instructors' encouragement help children keep studying every day.", "start": 184.75, "end": 190.34, "words": []}, "l4_5": {"scene": "s4", "text": "Over time, progress reports should show parents what their child can now do on their own and what they will learn next.", "start": 191.04, "end": 196.95, "words": []}, "l4_6": {"scene": "s4", "text": "Our first priority is parents of children in Grades 1 to 4 who want to understand where their child is having difficulty.", "start": 197.65, "end": 203.41, "words": []}, "l4_7": {"scene": "s4", "text": "For Grades 1 and 2, we focus on building regular study habits and independent learning skills.", "start": 204.11, "end": 209.52, "words": []}, "l4_8": {"scene": "s4", "text": "For Grades 2 to 4, we focus on identifying learning gaps and areas of difficulty.", "start": 210.22, "end": 214.87, "words": []}, "l4_9": {"scene": "s4", "text": "Seven-year-olds preparing for elementary school and students in Grades 5 and 6 are also important target groups.", "start": 215.57, "end": 221.46, "words": []}, "l5_1": {"scene": "s5", "text": "Our key differentiation is not simply better grading.", "start": 222.91, "end": 226.11, "words": []}, "l5_2": {"scene": "s5", "text": "It is how we connect assessment results to individualized learning and make each child's progress visible.", "start": 226.81, "end": 232.36, "words": []}, "l5_3": {"scene": "s5", "text": "We use assessment to find where each child needs help.", "start": 233.06, "end": 236.07, "words": []}, "l5_4": {"scene": "s5", "text": "Based on the results, we select appropriate workbooks, determine the starting level, and design an individualized learning path.", "start": 236.77, "end": 243.25, "words": []}, "l5_5": {"scene": "s5", "text": "Instructors check their work, coach them where needed, and adjust their learning pace.", "start": 243.95, "end": 248.66, "words": []}, "l5_6": {"scene": "s5", "text": "Then, we assess students again and use progress reports to see what has changed and set the next learning goal.", "start": 249.36, "end": 255.19, "words": []}, "l5_7": {"scene": "s5", "text": "This is how we connect assessment, individualized learning, and instructor coaching to each child's actual progress.", "start": 255.89, "end": 262.05, "words": []}, "l5_8": {"scene": "s5", "text": "Progress reports should not simply present information in a better format.", "start": 262.75, "end": 266.92, "words": []}, "l5_9": {"scene": "s5", "text": "They should provide clear evidence of how our learning system works and how children are improving.", "start": 267.62, "end": 272.3, "words": []}, "l6_1": {"scene": "s6", "text": "JEI aims to be a brand that helps children build the ability to grow on their own through precise assessment and personalized learning paths designed for each child.", "start": 273.75, "end": 282.97, "words": []}, "l6_2": {"scene": "s6", "text": "For parents, precise assessment is a reason to choose JEI.", "start": 283.67, "end": 287.4, "words": []}, "l6_3": {"scene": "s6", "text": "The core of our service is using assessment results to choose the right learning materials and learning sequence for each child.", "start": 288.1, "end": 294.32, "words": []}, "l6_4": {"scene": "s6", "text": "Our goal is to help children understand more and solve more problems on their own.", "start": 295.02, "end": 299.47, "words": []}, "l6_5": {"scene": "s6", "text": "This is based on JEI's philosophy:", "start": 300.17, "end": 302.58, "words": []}, "l6_6": {"scene": "s6", "text": "\"We believe in the power of self-learning.\"", "start": 303.28, "end": 305.6, "words": []}, "l6_7": {"scene": "s6", "text": "Our message to customers is:", "start": 306.3, "end": 308.07, "words": []}, "l6_8": {"scene": "s6", "text": "\"What your child needs to learn. The power to learn independently.\"", "start": 308.77, "end": 312.22, "words": []}, "l6_9": {"scene": "s6", "text": "We can explain this message in one sentence:", "start": 312.92, "end": 315.37, "words": []}, "l6_10": {"scene": "s6", "text": "\"Start with a precise assessment and focus on what your child needs to learn now.\"", "start": 316.07, "end": 320.49, "words": []}, "l6_11": {"scene": "s6", "text": "In our advertising and on our website, we will show how we check each child's level and help them learn step by step in the right order.", "start": 321.19, "end": 328.37, "words": []}, "l6_12": {"scene": "s6", "text": "When meeting with parents, we will start by asking, \"What should your child learn first?\"", "start": 329.07, "end": 333.63, "words": []}, "l6_13": {"scene": "s6", "text": "Rather than simply promoting personalized learning or AI features, we need to show parents what their child needs to learn and how their child is improving.", "start": 334.33, "end": 342.69, "words": []}, "l7_1": {"scene": "s7", "text": "We need to connect JEI's strengths in assessment and learning management across subjects.", "start": 344.14, "end": 348.99, "words": []}, "l7_2": {"scene": "s7", "text": "First, we will set clear standards for assessment and learning plans.", "start": 349.69, "end": 353.54, "words": []}, "l7_3": {"scene": "s7", "text": "Then, we will expand from Math to Korean and English.", "start": 353.99, "end": 357.38, "words": []}, "l7_4": {"scene": "s7", "text": "Second, we will connect paper-based learning and instructor coaching with digital progress reports.", "start": 358.08, "end": 363.49, "words": []}, "l7_5": {"scene": "s7", "text": "These reports should help parents track their child's progress through mobile apps and parent consultations.", "start": 364.19, "end": 369.52, "words": []}, "l7_6": {"scene": "s7", "text": "We can also explore how our Learning Centers and personalized POD workbooks could work together.", "start": 370.22, "end": 375.44, "words": []}, "l7_7": {"scene": "s7", "text": "In addition, we need to focus not only on new enrollment but also on student retention, the number of subjects per member, and revenue per customer.", "start": 376.14, "end": 384.21, "words": []}, "l7_8": {"scene": "s7", "text": "We will check our results using enrollment rates after assessment, reassessment rates, report viewing rates, and retention rates.", "start": 384.91, "end": 391.94, "words": []}, "l8_1": {"scene": "s8", "text": "In the end, parents should be able to explain how their child's learning has changed and what the next learning goal is.", "start": 393.39, "end": 399.2, "words": []}, "l8_2": {"scene": "s8", "text": "Our goal is to connect precise assessment, individualized learning, and instructor coaching, and make each child's progress visible to parents.", "start": 399.9, "end": 407.9, "words": []}, "l8_3": {"scene": "s8", "text": "This is the reason we want parents to choose JEI.", "start": 408.6, "end": 411.78, "words": []}, "l8_4": {"scene": "s8", "text": "This concludes my presentation.", "start": 412.48, "end": 414.3, "words": []}, "l8_5": {"scene": "s8", "text": "Thank you.", "start": 415.0, "end": 415.69, "words": [["thank", 414.82], ["you", 415.26]]}}};
